'use strict';
function backLink(path='home',label='机构列表'){return `<a class="back" href="#${path}">返回${label}</a>`}
function materialRow(m){return `<a class="record-row" href="#material/${m.id}">${imageHTML(m.image,'AI 生成示意媒体')}<div><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p><span class="muted">${kindIcon(m.kind)}${m.kind} · ${m.date.replaceAll('-','.')} · 演示资料</span></div></a>`}
function storyRow(s){return `<a class="record-row story-row" href="#story/${s.id}">${imageHTML('assets/documents.webp','AI 生成纸面记录示意')}<div><h3>${esc(s.title)}</h3><p>“${esc(s.paragraphs[0].slice(0,35))}……”</p><span class="muted">${icon('pencil-line')}${esc(s.author)} · 虚构经历</span></div></a>`}
function contributionNote(id){return `<div class="soft-note contribution-note"><div><h3>你知道更多相关信息吗？</h3><p>资料、不同的经历，或需要更正的内容，都可以先整理下来。</p></div><a href="#feedback/${id||''}">${icon('message-circle')}补充或更正</a></div>`}
function sharedAction(type,id){return `<div class="detail-actions"><button class="primary" data-share="${type}/${id}">${icon('share-2')}分享与保存</button><a class="button" href="#about">${icon('info')}资料说明</a></div>`}
function renderInstitution(i){if(i.isSource)return renderSourceInstitution(i);const ms=i.materials.map(getMaterial),ss=i.stories.map(id=>stories.find(s=>s.id===id));return `<div class="content-column">${backLink()}<header class="detail-header"><div class="heading-line"><h1>${esc(i.name)}</h1><span class="meta location">${icon('map-pin')}${i.region} · ${i.city}</span></div><p class="muted">曾用名：${esc(i.alias)} · 更新于 ${DATA.updated.replaceAll('-','.')}</p></header><div class="media-strip large"><a href="#material/${ms[0].id}">${imageHTML('assets/campus.webp','AI 生成校园示意，不是真实机构照片')}<span class="media-label">${icon('building-2')}机构示意</span></a><a href="#material/${ms[0].id}">${imageHTML('assets/documents.webp','AI 生成文件示意')}<span class="media-label">${icon('file-text')}资料示意</span></a><a href="#material/${ms.at(-1).id}">${imageHTML(ms.at(-1).image,'AI 生成相关影像示意')}<span class="media-label">${kindIcon(ms.at(-1).kind)}${ms.at(-1).kind==='视频'?'播放 · 00:08':'关联资料'}</span></a></div><p class="detail-intro">这里整理了机构的公开材料与经历记录。<br>不同材料分别注明来源，缺少的信息可以继续补充。</p><div class="tabs" role="tablist" aria-label="机构内容"><button role="tab" data-inst-tab="materials" data-inst="${i.id}" aria-selected="true" aria-controls="institution-tab-content">${icon('files')}资料</button><button role="tab" data-inst-tab="stories" data-inst="${i.id}" aria-selected="false" aria-controls="institution-tab-content">${icon('pencil-line')}经历</button><button role="tab" data-inst-tab="updates" data-inst="${i.id}" aria-selected="false" aria-controls="institution-tab-content">${icon('history')}更新</button></div><section id="institution-tab-content" role="tabpanel" aria-label="资料"><h2 class="section-head">公开资料</h2>${ms.map(materialRow).join('')}${ss.length?`<h2 class="section-head spaced">经历记录</h2>${ss.map(storyRow).join('')}`:''}</section>${contributionNote(i.id)}${sharedAction('institution',i.id)}<p class="muted small-print">机构名称、文字和媒体全部为虚构示例，不能用于指认真实机构。</p></div>`}
function renderMaterial(m){const i=getInstitution(m.institution);return `<div class="content-column">${backLink(i?'institution/'+i.id:'browse',i?i.name:'资料列表')}<header class="detail-header"><p class="eyebrow">${m.region} · ${m.kind}</p><h1>${esc(m.title)}</h1><p class="muted">整理于 ${m.date.replaceAll('-','.')} · ${m.id} · v${m.version}</p></header>${m.kind==='视频'?`<video class="media-view" controls playsinline preload="metadata" poster="${m.image}" aria-label="8秒生成示意视频"><source src="${m.file}" type="video/mp4"><a href="${m.file}">下载视频</a></video>`:imageHTML(m.image,'AI 生成示意图片，非真实记录','media-view')}<p class="caption">AI 生成示意${m.kind==='视频'?'视频 · 00:08':'图片'}，非现场资料</p><article class="reading"><h2>材料说明</h2>${m.body.map(p=>`<p>${esc(p)}</p>`).join('')}<h2 class="icon-heading">${icon('file-text')}来源与版本</h2><p>${esc(m.source)}。本条目用于检查资料展示、播放与保存流程，没有真实投稿或独立核实。</p>${i?`<a class="linked-institution" href="#institution/${i.id}"><span class="muted icon-heading">${icon('building-2')}相关机构</span><strong>${i.name}</strong><span>${i.region} · ${i.city}</span></a>`:''}<details class="source-details"><summary>查看保存包内容</summary><p>资料说明、公开记录 JSON、${m.kind==='视频'?'MP4 视频':'图片'}与 SHA256 校验清单。保留演示标记，不包含私人投稿。</p></details></article>${contributionNote(m.institution)}${sharedAction('material',m.id)}</div>`}
function renderStory(s){const i=getInstitution(s.institution);return `<div class="content-column reading-column">${backLink('institution/'+i.id,i.name)}<header class="detail-header"><p class="eyebrow">经历记录 · 虚构示例</p><h1>${esc(s.title)}</h1><p class="muted">${esc(s.author)} · ${s.date.replaceAll('-','.')}</p></header><a class="linked-institution" href="#institution/${i.id}"><span class="muted icon-heading">${icon('building-2')}与这段经历相关</span><strong>${i.name}</strong><span>${i.region} · ${i.city}</span></a><article class="reading story-copy">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<h2>一同留下的资料</h2><div class="attachment-grid">${s.attachments.map(getMaterial).map(m=>`<a href="#material/${m.id}">${imageHTML(m.image,'AI 生成关联资料示意')}<span>${esc(m.title)}</span></a>`).join('')}</div><div class="warm-note">记录可以慢慢补充，已有内容也可以更正。</div><p class="muted">本文与署名均为虚构示例，图片和视频为 AI 生成示意；没有真实当事人的公开证词。</p></article>${contributionNote(i.id)}${sharedAction('story',s.id)}</div>`}
function renderBrowse(){return `<div class="page-title"><h1>资料与影像</h1><div class="search-bar"><input id="material-query" type="search" placeholder="资料标题、地区或机构" aria-label="搜索资料"><select id="material-kind" aria-label="资料类型"><option value="all">所有类型</option><option>图片</option><option>视频</option><option>图文</option></select></div></div><div class="heading-line"><h2>公开资料</h2><span class="muted" id="material-count" role="status"></span></div><div class="materials-grid" id="material-results"></div>`}
function renderMaterialResults(){const q=$('material-query').value.trim().toLowerCase(),kind=$('material-kind').value;const rows=materials.filter(m=>(kind==='all'||m.kind===kind)&&(!q||[m.title,m.region,m.summary,getInstitution(m.institution)?.name].join(' ').toLowerCase().includes(q)));$('material-count').textContent=rows.length+' 份演示资料';$('material-results').innerHTML=rows.length?rows.map(m=>`<article class="material-tile"><a href="#material/${m.id}"><div class="tile-cover">${imageHTML(m.image,'AI 生成资料示意')}<span>${kindIcon(m.kind)}${m.kind}${m.kind==='视频'?' · 00:08':''}</span></div><div class="tile-copy"><span class="muted">${m.region} · ${getInstitution(m.institution)?.name||'保存与传播'}</span><h2>${esc(m.title)}</h2><p>${esc(m.summary)}</p></div></a></article>`).join(''):`<div class="empty"><h3>没有匹配的资料</h3><p>试试其他关键词或资料类型。</p></div>`}
function renderParticipate(){return `<div class="content-column"><div class="page-title"><h1>一起留下资料，也互相支持</h1><p class="muted">一次只整理一点，也可以。</p></div><div class="participate-entries"><a href="#provide"><h2 class="icon-heading">${icon('folder-open')}整理资料</h2><p>提供戒网瘾机构资料、来源及图片视频，先保存再确认提交。</p></a><a href="#mutual"><h2 class="icon-heading">${icon('users-round')}互助交流</h2><p>交流求助、资料整理与保存传播。</p></a><a href="#feedback"><h2 class="icon-heading">${icon('message-circle')}反馈与更正</h2><p>记录补充信息，指出内容或公开范围的问题。</p></a></div><div class="notice">机构资料与反馈已接入私人收件。可以保存服务器草稿，提交后持回执查看处理进度；离线时仍可保存说明和原件。</div><div class="inline-actions spaced"><a class="button" href="#intake-status">私人回执与进度</a><a class="button" href="#access">手机入口与备用保存</a></div><h2 class="section-head spaced">经历记录 · 虚构演示</h2>${stories.map(storyRow).join('')}</div>`}
function renderMutual(){return `<div class="content-column">${backLink('participate','参与')}<div class="heading-line page-title"><h1>互助交流</h1><a href="#topic-draft">${icon('pencil-line')}写下一个问题</a></div><p class="muted">资料整理、保存与经历记录，都可以成为交流的起点。</p><div class="notice">帖子与回复均为虚构示例。这里只能保存提问草稿，尚未开放注册、发帖和回复。</div>${DATA.topics.map(t=>`<a class="topic-row" href="#topic/${t.id}"><span class="eyebrow">${t.tag}</span><h2>${t.title}</h2><p>${t.intro}</p><span class="muted">${t.replies.length} 条示例回复</span></a>`).join('')}</div>`}
function renderTopic(t){return `<div class="content-column">${backLink('mutual','互助交流')}<header class="detail-header"><p class="eyebrow">${t.tag} · 演示讨论</p><h1>${t.title}</h1></header><article class="reading"><p>${t.body}</p></article><h2 class="section-head">一起补充</h2>${t.replies.map((r,n)=>`<div class="reply"><p class="muted">示例参与者 ${n+1}</p><p>${r}</p></div>`).join('')}<a class="button" href="#topic-draft">整理自己的问题</a></div>`}
function renderTopicDraft(){return `<div class="content-column">${backLink('mutual','互助交流')}<h1>先把问题写下来</h1><p class="muted">可以先保存，想好了再决定怎样交流。</p><form id="topic-form"><label class="form-field"><span>问题标题</span><input type="text" name="title" required maxlength="150"></label><label class="form-field"><span>想补充的背景</span><textarea name="background" required maxlength="10000"></textarea></label><p class="notice">保存到自己的设备，不会发布或提交。请不要写入他人的私人联系方式。</p><button class="primary" type="submit">${icon('save')}保存问题草稿</button></form></div>`}
function renderFeedback(id=''){return `<div class="content-column">${backLink('participate','参与')}<h1>补充、反馈与更正</h1><p class="muted">告诉我们是哪一部分，以及你希望怎样处理。</p><form id="feedback-form"><label class="form-field"><span>相关机构或资料</span><input type="text" name="target" value="${esc(getInstitution(id)?.name||getMaterial(id)?.title||id)}" placeholder="名称、编号或链接" required maxlength="500"></label><label class="form-field"><span>需要处理什么？</span><select name="category"><option>资料补充</option><option>事实或来源需要更正</option><option>个人信息与公开授权问题</option><option>访问或下载问题</option><option>其他反馈</option></select></label><label class="form-field"><span>具体说明与希望的处理</span><textarea name="description" placeholder="可写明需要更正的位置、理由和已有来源。不确定的部分可以注明。" required maxlength="20000"></textarea></label><label class="form-field"><span>可以核对的公开来源（选填）</span><input type="text" name="source" maxlength="2000" placeholder="公开页面地址或文件说明"></label><p class="notice">当前只保存反馈草稿，不会发送，也不会获得受理编号。需要私下说明的身份与联系方式不应写入公开资料包。</p><button type="submit" class="primary">${icon('save')}保存反馈草稿</button></form><details class="source-details spaced"><summary>之后会怎样处理？</summary><p>正式接入收件后：接收反馈 → 检查相关内容与风险 → 需要时先限制相关个人信息展示 → 补充核对与回应 → 更正公开版本并通知受管理副本。资料不足先记录为待补充，不自动认定违法，也不把投诉本身当作事实结论。</p></details></div>`}
function renderReview(){return `<div class="content-column">${backLink('about','关于')}<h1>资料处理流程演示</h1><p class="notice">这是可公开查看的虚构流程示例，既不是管理后台，也没有真实投稿、敏感原件或管理员权限。</p><div class="review-layout"><section><h2>示例线索 · R-001</h2><p class="muted">有关一段经历的资料 · 尚未确认背景</p><div class="reading"><p>提供者记得大致时间，但图片来源和公开授权尚未说明。</p><h3>需要补充</h3><p>文件取得方式、能够确认的时间、涉及人员的公开范围。身份确认与材料真实性分别处理。</p></div><label class="form-field"><span>处理说明（本页演示）</span><textarea id="review-note" placeholder="写下需要补充的问题，不预设结论。"></textarea></label><div class="inline-actions"><button class="primary" data-review="需要补充">标记需要补充</button><button data-review="暂不公开">暂不公开</button></div><p id="review-status" class="notice" role="status">演示状态：待查看。当前不满足公开条件。</p></section><aside class="soft-note"><h3>公开前逐项确认</h3><ul><li>来源与陈述分开标明</li><li>无授权个人信息不进入公开包</li><li>核对导出文件里的脸部、姓名与位置</li><li>留存可追溯的版本和更正入口</li></ul><button disabled>生成公开版本（条件未满足）</button></aside></div></div>`}
function renderAbout(){return `<div class="content-column"><h1>关于戒网瘾机构观察</h1><article class="reading"><p>围绕戒网瘾机构整理公开资料与经历，让材料被看见，也能被完整保存。服务范围为中国大陆。机构来源目录已接入1251份已有记录，尚待本站逐项核对。旧资料与经历示例仍明确标为虚构；投稿、反馈和互助区可实际提交。</p><h2>一份资料，不只是一张图片</h2><p>图片、视频、文字说明、来源与版本一起保留。读者可以保存单份材料、机构资料包，或者下载整站公开文件，再从同一套文件继续阅读与发布。</p><h2>公开资料与私人原件分别保存</h2><p>手机选入的文件起初只在设备上整理。主动保存服务器草稿或提交时才上传；可以只保存本机草稿与私人包。整站下载包含公开来源目录和标明虚构的演示文件，不包含私人投稿、回执、数据库或原件。</p><h2>来源、身份与授权各自说明</h2><p>确认一个人的身份不等于确认材料真实。公开署名、账号核验、原件核对与公开授权需要分别处理。互助账号、帖子与审核后台已接通试用；机构资料和反馈已接入收件及回执进度；国内公众访问和独立身份入口仍需实测与适配。</p></article><div class="about-actions"><a class="button primary" href="#access">手机入口与备用保存</a><a class="button" href="source-catalog.json" download>下载1251份来源目录</a><a class="button primary" href="site-copy.zip" download="看见-公开网站-v0.2.zip">${icon('package')}下载整站公开包</a><a class="button" href="public-data.json" download>${icon('download')}下载公开目录 JSON</a><a class="button" href="tools/media-pack.html">${icon('video')}图片视频分包与还原工具</a><a class="button" href="#review">${icon('files')}查看审核流程演示</a><a class="button" href="#feedback">${icon('message-circle')}补充与更正</a><a class="button" href="README.txt" download>${icon('file-text')}保存复制发布说明</a></div><details class="source-details"><summary>复制与使用说明</summary><p>整站包解压后打开 index.html 即可在支持本地网页脚本的浏览器中阅读；手机文件预览器可能不执行脚本。将解压出的文件原样上传静态托管目录即可发布，无需安装程序或连接原站。媒体、说明与工具全部随包保存。公开托管需要另行核对平台条款、资料授权与访问效果。</p><p>分包工具是按字节分装和完整还原，不是剪辑成可以分别播放的视频，也没有自动上传。手机可播放的裁剪与拼接仍需要后续实现。</p></details><details class="source-details"><summary>地图与示意素材</summary><p>地区边界数据来自阿里云 DataV：<a href="https://help.aliyun.com/zh/datav/datav-atlas/developer-reference/atlas-sdk-introduction" target="_blank" rel="noopener">官方数据源示例</a>。本页为筛选功能预览，尚未完成地图公开使用所需的底图、标注与使用权核查。未纳入服务范围的地区不提供档案筛选。</p><p>演示档案的三张媒体图片由 AI 生成，视频由生成图片制作。没有用它们展示真实机构或指认违法。示例文字不是真实证词。</p></details><a class="button source-reference" href="#source-example">${icon('image')}查看真实来源照片示例</a><details class="source-details"><summary>图标来源与使用</summary><p>界面图标采用 <a href="https://lucide.dev/license" target="_blank" rel="noopener">Lucide</a> 统一线条图标。图标只说明用途，不表示资料已核实或身份已认证；来源与许可随整站包一并保存。</p><a href="assets/icons/LICENSE.txt" download>保存图标许可</a></details><p class="muted small-print">阶段版本 v${DATA.version} · ${DATA.updated}。国内访问效果、微信内置浏览器和实际手机大文件处理尚需测试。</p></div>`}

function renderExperiences(){return `<div class="content-column"><h1>经历记录</h1><p class="muted">与机构和相关资料相连，保留背景，也保留不确定的部分。</p><div class="notice">以下均为虚构经历，用于查看阅读结构，不是真实证词。</div>${stories.map(storyRow).join('')}</div>`}
function renderSourceExample(){return `<div class="content-column">${backLink('about','关于')}<p class="eyebrow">真实来源照片 · 素材使用示例</p><h1>临沂市第四人民医院外景</h1><p class="muted">照片拍摄于 2016 年，展示当时的建筑外观。</p>${imageHTML('assets/linyi-exterior-2016.jpg','临沂市第四人民医院外景，夜眼摄，2016年11月5日','media-view')}<div class="reading"><p>作者：夜眼。拍摄日期：2016-11-05。来源：<a href="https://commons.wikimedia.org/wiki/File:The_Fourth_Hospital_of_Linyi_(Linyi_Mental_Hospital)_01.jpg" target="_blank" rel="noopener">Wikimedia Commons 原始说明页</a>。</p><p>许可：<a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>。使用上游 1280px 缩略图，未进一步修改；此图片继续按该许可提供。作者未为本站背书。</p><p>这里只演示真实照片与作者、日期、许可的配套展示。照片没有关联到任何虚构机构档案，也不用于证明不当行为、当前状态或目前业务。</p></div><a class="button" href="assets/real-photo-credit.txt" download>${icon('file-text')}保存照片来源与许可说明</a></div>`}
